def parse(G):
    seps=[i for i in range(len(G)) if len(set(G[i]))==1]
    sepcols=[j for j in range(len(G[0])) if len({G[i][j] for i in range(len(G))})==1]
    rb=list(zip([0]+[s+1 for s in seps],[s for s in seps]+[len(G)]))
    cb=list(zip([0]+[s+1 for s in sepcols],[s for s in sepcols]+[len(G[0])]))
    blocks=[]
    for i,(r0,r1) in enumerate(rb):
        for j,(c0,c1) in enumerate(cb):
            B=[row[c0:c1] for row in G[r0:r1]]
            blocks.append(((i,j),B))
    return blocks

