def feats(Gd, outd, base):
    bl={}
    for (i,j),B in parse(Gd): bl[(i,j)]=B
    R=max(i for i,j in bl)+1; C=max(j for i,j in bl)+1
    res=[]
    for i in range(R):
        for j in range(C):
            B=bl[(i,j)]
            S={(r,c) for r in range(len(B)) for c in range(len(B[0])) if B[r][c]!=base}
            L=bl.get((i,j-1)); T=bl.get((i-1,j))
            def spec(Bx): return {(r,c) for r in range(len(Bx)) for c in range(len(Bx[0])) if Bx[r][c]!=base}
            dl=len(S^spec(L)) if L else None
            dt=len(S^spec(T)) if T else None
            res.append(((i,j),outd[i][j],len(S),dl,dt,S))
    return res
