from collections import Counter
def test_uniqueness(Gd, outd, base):
    bl={}
    for (i,j),B in parse(Gd): bl[(i,j)]=B
    R=max(i for i,j in bl)+1; C=max(j for i,j in bl)+1
    cols={j:[bl[(i,j)] for i in range(R)] for j in range(C)}
    rows={i:[bl[(i,j)] for j in range(C)] for i in range(R)}
    ok=True
    for i in range(R):
        for j in range(C):
            S={(r,c) for r in range(len(bl[(i,j)])) for c in range(len(bl[(i,j)][0])) if bl[(i,j)][r][c]!=base}
            colpos=Counter()
            for B in cols[j]:
                colpos.update((r,c) for r in range(len(B)) for c in range(len(B[0])) if B[r][c]!=base)
            rowpos=Counter()
            for B in rows[i]:
                rowpos.update((r,c) for r in range(len(B)) for c in range(len(B[0])) if B[r][c]!=base)
            uc=sum(1 for p in S if colpos[p]==1)
            ur=sum(1 for p in S if rowpos[p]==1)
            # also count of 5s at rel positions shared by others
            if uc!=outd[i][j] and ur!=outd[i][j]:
                print("mismatch",(i,j),"out",outd[i][j],"uc",uc,"ur",ur,"count",len(S))
                ok=False
    print("done ok=",ok)
