import itertools
def blocklist(Gd):
    bl={}
    for (i,j),B in parse(Gd): bl[(i,j)]=B
    return bl
def analyze(Gd,outd,base):
    bl=blocklist(Gd)
    R=max(i for i,j in bl)+1; C=max(j for i,j in bl)+1
    data={}
    for i in range(R):
        for j in range(C):
            B=bl[(i,j)]; h=len(B); w=len(B[0])
            S={(r,c) for r in range(h) for c in range(w) if B[r][c]!=base}
            f={}
            f['count']=len(S)
            f['nrows']=len({r for r,c in S})
            f['ncols']=len({c for r,c in S})
            f['border']=sum(1 for r,c in S if r in(0,h-1) or c in(0,w-1))
            f['interior']=len(S)-f['border']
            f['orthoadj']=sum(1 for r,c in S if (r+1,c) in S or (r,c+1) in S)
            f['diagadj']=sum(1 for r,c in S if (r+1,c+1) in S or (r+1,c-1) in S)
            f['maindiag']=sum(1 for r,c in S if r==c)
            f['antidiag']=sum(1 for r,c in S if r+c==h-1 or r+c==w-1)
            f['midrow']=sum(1 for r,c in S if r==h//2)
            f['midcol']=sum(1 for r,c in S if c==w//2)
            f['firstrow']=sum(1 for r,c in S if r==0)
            f['lastrow']=sum(1 for r,c in S if r==h-1)
            f['firstcol']=sum(1 for r,c in S if c==0)
            f['lastcol']=sum(1 for r,c in S if c==w-1)
            f['evenrows']=sum(1 for r,c in S if r%2==0)
            f['oddrows']=sum(1 for r,c in S if r%2==1)
            f['rowsum']=sum(r for r,c in S)
            f['colsum']=sum(c for r,c in S)
            data[(i,j)]=(f,outd[i][j])
    return data
